import{_ as l,o as a,c as i,ag as e}from"./chunks/framework.CtWPcAmt.js";const p=JSON.parse('{"title":"第 13 章：从模板进阶到 Skill","description":"Skill 解决什么问题、与提示词/规则/脚本的区别、四件套结构、何时该建何时不该；拆解一个作者的 Skill。","frontmatter":{"title":"第 13 章：从模板进阶到 Skill","description":"Skill 解决什么问题、与提示词/规则/脚本的区别、四件套结构、何时该建何时不该；拆解一个作者的 Skill。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/13-skills.md","filePath":"guide/13-skills.md","lastUpdated":null}'),r={name:"guide/13-skills.md"};function s(o,t,n,d,h,k){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-13-章-从模板进阶到-skill" tabindex="-1">第 13 章：从模板进阶到 Skill <a class="header-anchor" href="#第-13-章-从模板进阶到-skill" aria-label="Permalink to &quot;第 13 章：从模板进阶到 Skill&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>模板帮你固化结构，但模板还有局限：它只是「文本」，Agent 每次都要重新理解；它不能带参考材料、不能带脚本、不能被产品识别为「一个能力」。<strong>Skill（技能）是模板的下一级</strong>：把指令、参考资料、脚本打包成一个可命名、可调用、可分享的能力单元。本章产出<strong>第一个最小可用 Skill</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>我反复做同一件事：把一张截图交给 AI 描述成结构化文字（第 5 章分析 18 张产品截图时）。每次都要写一大段「请用 JSON 结构描述图片，包含布局、区域、文字、不确定项……」。写了十几遍后，我把这段指令 + 调用脚本 + 输出模板打包成了一个「图像描述」Skill。从此一句话「描述这张图」即可，输出结构永远一致。</p><p><strong>模板省的是「打字」，Skill 省的是「理解」</strong>：Skill 被产品识别为正式能力，指令、脚本、参考资料一次打包，执行路径稳定。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>Skill 是什么</strong>：一个可复用的能力包 = 指令（告诉它怎么做）+ 参考资料（告诉它用什么知识）+ 脚本（可选，自动化动作）+ 资源（模板/示例）；</li><li><strong>Skill 与三者的区别</strong>：提示词是一次性的口语；项目规则是常驻的约束；脚本是纯代码；<strong>Skill 是「结构化打包 + 可调用 + 可分享」的能力单元</strong>；</li><li><strong>什么时候该建</strong>：同一任务重复 ≥3 次、每次都要大量重复解释、且结构稳定——值得建；</li><li><strong>什么时候不该建</strong>：做一次就完、结构天天变、或只是模板能解决——别建，复杂度不值得；</li><li><strong>最小可用原则</strong>：第一个 Skill 从「指令 + 一个模板」开始，能跑通就算成功，脚本和资源后面再加。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>Skill（技能）</strong>：产品能识别和调用的可复用能力包。白话解释：给你的 Agent 装一个「会做 X 事的插件」，你只需要说「用 X 技能做这件事」。</li><li><strong>指令（Instruction）</strong>：技能的核心文本，告诉 Agent 步骤、规则、输出格式。</li><li><strong>参考资料（Reference）</strong>：技能运行时要用的知识、示例、标准。</li><li><strong>脚本（Script）</strong>：技能触发的自动化代码（可选，如批量处理、调用工具）。</li><li><strong>Slash 命令</strong>：不少产品用 <code>/技能名</code> 快速调用 Skill（第 5 章 WorkBuddy 页有 <code>/</code> 调技能的界面记录）。</li></ul><h2 id="一个真实-skill-的拆解-作者的「图像描述」skill" tabindex="-1">一个真实 Skill 的拆解（作者的「图像描述」Skill） <a class="header-anchor" href="#一个真实-skill-的拆解-作者的「图像描述」skill" aria-label="Permalink to &quot;一个真实 Skill 的拆解（作者的「图像描述」Skill）&quot;">​</a></h2><blockquote><p>背景问题：需要把截图转成结构化文字，每次重复写指令。 为什么普通提示词不够：指令长且固定、要带输出 JSON 模板、要调用视觉模型脚本——打包后一次配置，处处可用。</p></blockquote><p>拆解四件套：</p><table tabindex="0"><thead><tr><th>组件</th><th>内容</th><th>作用</th></tr></thead><tbody><tr><td>指令</td><td>「用 JSON 结构描述图片：布局、区域、文字、不确定项标 uncertain；禁止编造」</td><td>定义怎么做、输出什么</td></tr><tr><td>参考</td><td>输出 JSON 模板示例</td><td>固定输出结构</td></tr><tr><td>脚本</td><td>调用视觉模型的 <code>describe_image.py</code></td><td>自动化「看图」动作</td></tr><tr><td>资源</td><td>无（后续可加示例库）</td><td>—</td></tr></tbody></table><p>实际效果：18 张产品截图批量分析（第 5 章界面讲解文档的素材来源），每张输出结构一致、可注入写作流程。<strong>注意：本教程的说明仅是方法示范，该 Skill 的具体内容属作者个人资产，此处不展开密钥与实现细节。</strong></p><h2 id="跟着做-创建你的第一个最小-skill" tabindex="-1">跟着做：创建你的第一个最小 Skill <a class="header-anchor" href="#跟着做-创建你的第一个最小-skill" aria-label="Permalink to &quot;跟着做：创建你的第一个最小 Skill&quot;">​</a></h2><h3 id="第一步-选一个「重复-≥3-次」的任务" tabindex="-1">第一步：选一个「重复 ≥3 次」的任务 <a class="header-anchor" href="#第一步-选一个「重复-≥3-次」的任务" aria-label="Permalink to &quot;第一步：选一个「重复 ≥3 次」的任务&quot;">​</a></h3><p>从第 12 章模板库里挑一个（如「输出格式模板」对应的任务）。</p><h3 id="第二步-写指令-核心-约-5–10-行" tabindex="-1">第二步：写指令（核心，约 5–10 行） <a class="header-anchor" href="#第二步-写指令-核心-约-5–10-行" aria-label="Permalink to &quot;第二步：写指令（核心，约 5–10 行）&quot;">​</a></h3><p>用命令式写：<strong>角色 → 步骤 → 规则 → 输出格式</strong>。示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是【输出格式助手】。</span></span>
<span class="line"><span>步骤：</span></span>
<span class="line"><span>1. 读取输入材料；</span></span>
<span class="line"><span>2. 按模板结构组织；</span></span>
<span class="line"><span>3. 输出前自检：是否覆盖全部材料、格式是否符合模板。</span></span>
<span class="line"><span>规则：不虚构数据；来源无法确认时标注「未验证」。</span></span>
<span class="line"><span>输出格式：遵循【模板文件】。</span></span></code></pre></div><h3 id="第三步-打包-按你的产品方式" tabindex="-1">第三步：打包（按你的产品方式） <a class="header-anchor" href="#第三步-打包-按你的产品方式" aria-label="Permalink to &quot;第三步：打包（按你的产品方式）&quot;">​</a></h3><p>不同产品对 Skill 的存放位置/格式不同（第 5 章各产品页有入口记录：WorkBuddy 的「技能与指令」、Hermes 的「技能与工具」等）。把「指令 + 模板」保存为技能文件，命名清晰（如 <code>weekly-report</code>）。</p><h3 id="第四步-调用并验证" tabindex="-1">第四步：调用并验证 <a class="header-anchor" href="#第四步-调用并验证" aria-label="Permalink to &quot;第四步：调用并验证&quot;">​</a></h3><p>用 <code>/weekly-report</code> 或「用 weekly-report 技能……」调用一次，对照验收清单检查，迭代 v1.1。</p><h2 id="一个完整示例-最小-skill-的完整流程" tabindex="-1">一个完整示例（最小 Skill 的完整流程） <a class="header-anchor" href="#一个完整示例-最小-skill-的完整流程" aria-label="Permalink to &quot;一个完整示例（最小 Skill 的完整流程）&quot;">​</a></h2><ol><li><strong>问题</strong>：每周生成「项目周报」；</li><li><strong>普通提示词不够的原因</strong>：格式口径每次重写、且容易不一致；</li><li><strong>Skill 设计</strong>：指令（读 CONTEXT.md 状态 + 按模板生成）+ 参考（周报模板）；</li><li><strong>一次执行</strong>：<code>/weekly-report 本周完成：A、B；下周：C</code> → 输出固定格式周报；</li><li><strong>已知限制</strong>：需要 CONTEXT.md 存在；数据口径变化时要更新模板；</li><li><strong>后续改进</strong>：接入「自动收集 Git 提交」脚本（升级为带脚本的完整版）。</li></ol><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>Skill 建了一堆，几乎没用</td><td>为建而建</td><td>回到「重复 ≥3 次」标准，删掉低频的</td></tr><tr><td>Skill 和提示词没区别</td><td>只有指令没打包参考/脚本</td><td>把模板、示例、脚本都收进技能包</td></tr><tr><td>不同产品里 Skill 不通</td><td>格式/位置不同</td><td>学习产品规范；先做「文本版」通用技能</td></tr><tr><td>技能行为不稳定</td><td>指令模糊</td><td>步骤化 + 自检要求写清楚</td></tr><tr><td>一次都没验证就分享</td><td>没走验收</td><td>先用真实任务验证再分享</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>Skill 里<strong>不要</strong>写死 API Key、账号、密码——需要时用变量占位或环境配置；</li><li>带脚本的 Skill 要审查脚本内容（它会在 Agent 环境里执行），不运行不明来源的脚本；</li><li>分享 Skill 前检查：有没有夹带个人信息、内部路径、公司机密。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>40 分钟：按「跟着做」创建你的第一个最小 Skill（指令 + 一个模板即可），用真实任务调用并验证一次，写 v1.0 与一条待改进项。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>第一个最小可用 Skill</strong>（命名清晰、指令完整、调用过、有版本记录）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>Skill = 指令 + 参考资料 + 脚本 + 资源，是一个能力单元；</li><li>重复 ≥3 次才建，最小可用起步；</li><li>与提示词/规则/脚本的区别：打包、可调用、可分享；</li><li>四件套里，指令是核心，脚本是加分项；</li><li>Skill 是个人工具箱的核心资产，也是 Harness（第五篇）的能力组件。</li></ol>`,37)])])}const g=l(r,[["render",s]]);export{p as __pageData,g as default};
